{
  "root_cause": "The unCheckAllInputsExcept method selects checkboxes by name attribute instead of the exclusive group attribute, so clicking the exclusive 'No symptoms' checkbox does not uncheck other symptom checkboxes.",
  "repair_strategy": "Update unCheckAllInputsExcept to select inputs by data-checkbox-exclusive-group when present, falling back to name attribute, ensuring the exclusive checkbox clears other options in the same group.",
  "edits": [
    {
      "path": "packages/nhsuk-frontend/src/nhsuk/components/checkboxes/checkboxes.js",
      "sha256": "b12e3c7a52e09c981155d2f727c5eb8358d420a487177c9a1e722c19da4c8af0",
      "before": "  /**
   * Uncheck other checkboxes
   *
   * Find any other checkbox inputs with the checkbox group value, and uncheck them.
   * This is useful for when a “None of these” checkbox is checked.
   *
   * @param {HTMLInputElement} $input - Checkbox input
   */
  unCheckAllInputsExcept($input) {
    const { checkboxExclusiveGroup: exclusiveGroup } = $input.dataset

    const allInputsWithSameName = document.querySelectorAll(
      `input[type="checkbox"][name="${$input.name}"]`
    )

    allInputsWithSameName.forEach(($inputWithSameName) => {
      const hasSameFormOwner = $input.form === $inputWithSameName.form

      // Uncheck all with same exclusive group by default, otherwise fall back to
      // GOV.UK Frontend behaviour to uncheck all with the same name attribute
      if (hasSameFormOwner && $inputWithSameName !== $input) {
        this.setInputState($inputWithSameName, false, exclusiveGroup)
      }
    })
  }",
      "after": "  /**
   * Uncheck other checkboxes
   *
   * Find any other checkbox inputs with the checkbox group value, and uncheck them.
   * This is useful for when a “None of these” checkbox is checked.
   *
   * @param {HTMLInputElement} $input - Checkbox input
   */
  unCheckAllInputsExcept($input) {
    const { checkboxExclusiveGroup: exclusiveGroup } = $input.dataset

    let selector
    if (exclusiveGroup) {
      selector = `input[type="checkbox"][data-checkbox-exclusive-group="${exclusiveGroup}"]`
    } else {
      selector = `input[type="checkbox"][name="${$input.name}"]`
    }

    const allInputs = document.querySelectorAll(selector)

    allInputs.forEach(($inputWithSameName) => {
      const hasSameFormOwner = $input.form === $inputWithSameName.form

      // Uncheck all with same exclusive group by default, otherwise fall back to
      // GOV.UK Frontend behaviour to uncheck all with the same name attribute
      if (hasSameFormOwner && $inputWithSameName !== $input) {
        this.setInputState($inputWithSameName, false, exclusiveGroup)
      }
    })
  }"
    }
  ],
  "expected_accessibility_effect": "Keyboard users can now clear previously ticked symptoms when selecting the exclusive 'No symptoms' option, satisfying WCAG 2.1.1 (Keyboard) and 4.1.2 (Name, Role, Value).",
  "functional_risks": [
    "Possible regression for checkboxes that rely on the previous name‑based selection when no exclusive group is defined; the fallback preserves existing behavior."
  ],
  "verification_requirements": [
    "After the fix, selecting 'No symptoms' after ticking cough and fever results in symptoms[cough] and symptoms[fever] being unset.",
    "Selecting a symptom after 'No symptoms' should clear the 'No symptoms' checkbox (existing behavior).",
    "Mouse interaction with the exclusive checkbox continues to work.",
    "Non‑exclusive checkboxes retain their mutual‑exclusion behavior."
  ]
}
